// Plain form submissions keep all mutations (including the switch) on the
// same authenticated, CSRF-protected path as the editor.
document.addEventListener("submit", event => {
  const message = event.target.dataset.confirm;
  if (message && !window.confirm(message)) event.preventDefault();
});

document.addEventListener("change", event => {
  if (event.target.matches("[data-autosubmit]")) event.target.form.requestSubmit();
});

const editor = document.querySelector("[data-question-form]");
if (editor) {
  const rows = editor.querySelector(".option-rows");
  const template = editor.querySelector("template");
  const add = editor.querySelector("[data-add-option]");

  function numberRows() {
    Array.from(rows.children).forEach((row, index) => {
      const text = row.querySelector('[type="text"]');
      const correct = row.querySelector('[type="checkbox"]');
      const prefix = `question[option_rows][${index}]`;
      const label = `Option ${index + 1}`;
      text.name = `${prefix}[text]`;
      text.placeholder = label;
      text.setAttribute("aria-label", label);
      correct.name = `${prefix}[correct]`;
      correct.setAttribute("aria-label", `${label} is correct`);
      row.querySelector("button").setAttribute("aria-label", `Remove option ${index + 1}`);
    });
  }

  add.addEventListener("click", () => {
    rows.append(template.content.cloneNode(true));
    numberRows();
    rows.lastElementChild.querySelector("input").focus();
  });

  rows.addEventListener("click", event => {
    const remove = event.target.closest("[data-remove-option]");
    if (!remove) return;
    const row = remove.closest(".option-row");
    const next = row.nextElementSibling || row.previousElementSibling;
    row.remove();
    numberRows();
    (next?.querySelector("input") || add).focus();
  });
}
// Only the current question index and running total live in this tab. Nothing
// is submitted, put in browser storage, or carried over to a fresh preview.
function runPreview(player) {
  const questions = player.querySelectorAll("template[data-question]");
  if (!questions.length) return;

  const current = player.querySelector("[data-current]");
  const result = player.querySelector(".result-card");
  const next = player.querySelector("[data-next]");
  let index = 0;
  let points = 0;

  function showQuestion() {
    current.replaceChildren(questions[index].content.cloneNode(true));
    result.hidden = true;
    next.hidden = true;
    next.textContent = index + 1 === questions.length ? "See score" : "Next question";
  }

  current.addEventListener("click", event => {
    const pick = event.target.closest(".play-option");
    if (!pick || pick.disabled) return;
    const right = pick.dataset.correct === "true";
    if (right) points++;
    pick.classList.add("is-picked");
    pick.parentElement.classList.add("is-locked", "is-revealed");
    for (const option of current.querySelectorAll(".play-option")) {
      option.disabled = true;
      if (option.dataset.correct === "true") {
        option.classList.add("is-correct");
        option.querySelector(".play-option__mark").hidden = false;
      }
    }
    const status = current.querySelector("[role=status]");
    status.hidden = false;
    status.classList.add(right ? "play-status--right" : "play-status--wrong");
    status.textContent = right ? "Correct!" : "Wrong!";
    next.hidden = false;
    next.focus();
  });

  next.addEventListener("click", () => {
    index++;
    if (index < questions.length) {
      showQuestion();
      current.querySelector("h1").focus();
    } else {
      current.replaceChildren();
      next.hidden = true;
      result.querySelector("[data-points]").textContent = points;
      result.hidden = false;
      result.querySelector("h1").focus();
    }
  });

  player.querySelector("[data-restart]").addEventListener("click", () => {
    index = 0;
    points = 0;
    showQuestion();
    current.querySelector("h1").focus();
  });
  showQuestion();
}

runPreview(document.querySelector("[data-preview]"));
